      "tipo": "GC",
      "causa_raiz": "Alocação massiva e contínua de memória gerenciada (GC.Alloc) no método Update através de concatenação repetitiva de strings ('s += i.ToString()') e instanciação de arrays ('new object[10000]'), gerando mais de 5 MB de lixo por frame e provocando pausas de coleta de lixo (GC collect) de até 25.84 ms.",
      "codigo_refatorado": "using System;
using System.Collections.Generic;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        [Header("Modos de Teste (Desative em Produção)")]
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;

        [Header("Configurações de Spawn")]
        public GameObject testPrefab;
        [Range(1, 20)]
        public float spawnRadius = 10f;
        [Range(1, 50)]
        public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;

        [Header("Cargas de Teste")]
        [Range(1, 512)]
        public int cpuScansPerFrame = 1;
        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;
        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");
        private MaterialPropertyBlock _propertyBlock;
        private readonly List<GameObject> _trackedObjects = new List<GameObject>();

        private void Awake()
        {
            _propertyBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                var emptyGo = new GameObject("Empty_" + i);
                _trackedObjects.Add(emptyGo);
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;

            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);

                Collider col = quad.GetComponent<Collider>();
                if (col != null)
                {
                    Destroy(col);
                }

                quad.name = "Overdraw_" + i;
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);

                Renderer r = quad.GetComponent<Renderer>();
                if (r != null)
                {
                    r.sharedMaterial = overdrawMaterial;
                }
            }
        }

        private void Update()
        {
            // Em produção, evite alocações descartáveis ou buscas lineares por frame.
            if (stressGc)
            {
                // Otimizado: evitar concatenações iterativas desnecessárias e arrays temporários que disparam o GC
            }

            if (stressCpu)
            {
                // Otimizado: evite FindObjectsOfType no Update. Utilize coleções mantidas em cache como _trackedObjects
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            Vector3 spawnPos = UnityEngine.Random.insideUnitSphere * spawnRadius;
            GameObject clone = Instantiate(testPrefab, spawnPos, Quaternion.identity);
            _trackedObjects.Add(clone);

            if (useUniqueMaterials)
            {
                Renderer renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    // Usa MaterialPropertyBlock para alterar cor sem instanciar novos materiais nem quebrar batching
                    renderer.GetPropertyBlock(_propertyBlock);
                    Color randomColor = new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value);
                    _propertyBlock.SetColor(ColorPropertyId, randomColor);
                    renderer.SetPropertyBlock(_propertyBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "Quando somamos textos diretamente com '+' em um loop, a Unity cria uma nova cópia de texto na memória a cada ciclo, sem reaproveitar nada. Além disso, criar grandes listas e matrizes no Update gera lixo que o Garbage Collector (o 'faxineiro' da memória) precisa limpar depois, e quando ele passa, ele congela o jogo por vários milissegundos. Também substituímos o acesso direto a 'renderer.material' por 'MaterialPropertyBlock', o que permite mudar cores sem clonar o material na memória."
    },
    {
      "tipo": "CPU",
      "causa_raiz": "Chamadas contínuas a 'GameObject.FindObjectsOfType<GameObject>()' dentro do método Update. Essa função realiza uma varredura completa em todos os objetos da cena através da camada nativa da Unity e aloca um array na heap toda vez que é executada, consumindo até 102 ms de tempo de processamento.",
      "codigo_refatorado": "using System;
using System.Collections.Generic;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public GameObject testPrefab;
        [Range(1, 20)]
        public float spawnRadius = 10f;
        [Range(1, 50)]
        public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;

        // Lista mantida para acesso rápido, evitando buscas lineares pela cena
        private readonly List<GameObject> _spawnedObjects = new List<GameObject>();
        private MaterialPropertyBlock _propertyBlock;
        private static readonly int BaseColorId = Shader.PropertyToID("_Color");

        private void Awake()
        {
            _propertyBlock = new MaterialPropertyBlock();
        }

        public IReadOnlyList<GameObject> GetAllTrackedObjects()
        {
            return _spawnedObjects;
        }

        public void SpawnOne()
        {
            if (testPrefab == null) return;

            GameObject clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            _spawnedObjects.Add(clone);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    renderer.GetPropertyBlock(_propertyBlock);
                    _propertyBlock.SetColor(BaseColorId, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value));
                    renderer.SetPropertyBlock(_propertyBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "Usar 'FindObjectsOfType' a cada frame é como revirar uma casa inteira procurando uma chave a cada segundo. A solução recomendada é registrar os objetos em uma lista ('cache') assim que eles são criados. Dessa forma, quando você precisa deles, basta olhar a lista instantaneamente, economizando tempo precioso da CPU."
    }
  ],
  "dicas_level_design": null
}

